<?php
/** نظرة شاملة للطالب (للقراءة): بيانات شخصية + ملخص أكاديمي ومالي وسلوكي. $s,$ov,$enrollments,$guardians */
$gender = ['male' => 'ذكر', 'female' => 'أنثى'][$s['gender']] ?? '—'; $initial = mb_substr($s['full_name'], 0, 1);
$age = !empty($s['birth_date']) ? (int)floor((time() - strtotime($s['birth_date'])) / 31557600) : null; $cur = $ov['current']; $at = $ov['attendance'];
$row = fn($l, $v) => '<div class="d-flex justify-content-between border-bottom py-1 small"><span class="text-muted">' . e($l) . '</span><span class="text-end">' . ($v !== null && $v !== '' ? $v : '<span class="text-muted">—</span>') . '</span></div>';
?>
<div class="row g-3">
 <div class="col-lg-4"><div class="card-s h-100"><div class="d-flex align-items-center gap-3 mb-3"><div class="rounded-circle d-grid place-items-center text-white fw-bold fs-3" style="width:64px;height:64px;background:var(--c-primary);display:grid;place-items:center"><?= e($initial) ?></div>
   <div><div class="fw-bold fs-5"><?= e($s['full_name']) ?></div><div class="text-muted small"><?= e($gender) ?><?= $age !== null ? ' · ' . $age . ' سنة' : '' ?></div></div></div>
  <h3 class="h6">البيانات الشخصية</h3>
  <?= $row('رقم الطالب', '<code dir="ltr">' . e($s['student_no']) . '</code>') ?><?= $row('المعرّف الثابت', '<span dir="ltr">' . e($ov['uid'] ?? '') . '</span>') ?>
  <?= $row('تاريخ الميلاد', $s['birth_date'] ? '<span dir="ltr">' . e($s['birth_date']) . '</span>' : null) ?><?= $row('مكان الميلاد', e($s['birth_place'] ?? '')) ?><?= $row('الجنسية', e($s['nationality'] ?? '')) ?>
  <?= $row('الهوية الوطنية', !empty($s['national_id']) ? '<span dir="ltr">' . e($s['national_id']) . '</span>' : null) ?><?= $row('الهاتف', !empty($s['phone']) ? '<span dir="ltr">' . e($s['phone']) . '</span>' : null) ?><?= $row('العنوان', e($s['address'] ?? '')) ?>
  <?= $row('فصيلة الدم', e($s['blood_type'] ?? '')) ?><?= $row('احتياجات خاصة', e($s['special_needs'] ?? '')) ?><?= $row('ملاحظات صحية', e($s['health_notes'] ?? '')) ?><?= $row('المدرسة السابقة', e($s['previous_school'] ?? '')) ?><?= $row('تاريخ الالتحاق', $s['admission_date'] ? '<span dir="ltr">' . e($s['admission_date']) . '</span>' : null) ?></div></div>
 <div class="col-lg-8">
  <div class="row g-3 mb-3">
   <div class="col-6 col-md-3"><div class="card-s text-center h-100"><div class="small text-muted">الصف والشعبة</div><div class="fw-bold"><?= $cur ? e($cur['grade_name'] . ' / ' . $cur['section_name']) : '—' ?></div><div class="small text-muted"><?= $cur ? 'رقم الكشف ' . (int)$cur['roll_no'] : e($ov['year'] ?? '') ?></div></div></div>
   <?php if ($at): ?><div class="col-6 col-md-3"><div class="card-s text-center h-100"><div class="small text-muted">نسبة الحضور</div><div class="fw-bold fs-4 <?= $at['rate'] !== null && $at['rate'] < 80 ? 'text-danger' : 'text-success' ?>"><?= $at['rate'] === null ? '—' : e($at['rate']) . '%' ?></div><div class="small text-muted">غياب <?= (int)$at['absent'] ?> · تأخر <?= (int)$at['late'] ?></div></div></div><?php endif; ?>
   <?php $lastT = $ov['terms'] ? end($ov['terms']) : null; if ($lastT): ?><div class="col-6 col-md-3"><div class="card-s text-center h-100"><div class="small text-muted">المعدل (<?= e($lastT['name']) ?>)</div><div class="fw-bold fs-4"><?= $lastT['average'] === null ? '—' : e($lastT['average']) . '%' ?></div><div class="small text-muted"><?= $lastT['rank'] ? 'الترتيب ' . (int)$lastT['rank'] . ' من ' . (int)$lastT['size'] : '' ?> <?= e($lastT['result'] ?? '') ?></div></div></div><?php endif; ?>
   <?php if ($ov['fees'] !== null): ?><div class="col-6 col-md-3"><div class="card-s text-center h-100"><div class="small text-muted">الرسوم (المتبقي)</div><?php foreach ($ov['fees'] as $c => $t): ?><div class="fw-bold <?= (float)$t['balance'] > 0 ? 'text-danger' : 'text-success' ?>"><?= e(number_format((float)$t['balance'], 2)) ?> <?= e($c) ?></div><?php endforeach; ?><?php if (!$ov['fees']): ?><div class="fw-bold">—</div><?php endif; ?></div></div><?php endif; ?>
  </div>
  <div class="card-s mb-3"><h3 class="h6">الأكاديمي</h3>
   <?php if ($cur): ?><div class="row small"><div class="col-sm-6"><?= $row('السنة الدراسية', e($ov['year'])) ?><?= $row('الصف', e($cur['grade_name'])) ?><?= $row('الشعبة', e($cur['section_name'])) ?></div><div class="col-sm-6"><?= $row('مشرف الشعبة', e($cur['homeroom'] ?? '')) ?><?= $row('تاريخ التسجيل', $cur['enrolled_on'] ? '<span dir="ltr">' . e($cur['enrolled_on']) . '</span>' : null) ?></div></div><?php else: ?><div class="text-muted small">غير مسجَّل في السنة الفعّالة.</div><?php endif; ?>
   <?php if ($ov['terms']): ?><h4 class="h6 mt-3">نتائج الفصول</h4><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>الفصل</th><th>المعدل</th><th>التقدير</th><th>الترتيب</th><th>النتيجة</th></tr></thead><tbody>
    <?php foreach ($ov['terms'] as $t): ?><tr><td><?= e($t['name']) ?></td><td><?= $t['average'] === null ? '—' : e($t['average']) . '%' ?></td><td><?= e($t['letter'] ?? '—') ?></td><td><?= $t['rank'] ? (int)$t['rank'] . '/' . (int)$t['size'] : '—' ?></td><td><?= e($t['result'] ?? '—') ?><?= empty($t['complete']) ? ' <span class="badge text-bg-warning">غير مكتمل</span>' : '' ?></td></tr>
     <?php if ($t['subjects']): ?><tr class="table-light"><td colspan="5"><div class="d-flex flex-wrap gap-2 small"><?php foreach ($t['subjects'] as $sb): ?><span class="badge text-bg-<?= $sb['passed'] ? 'light border' : 'danger' ?>"><?= e($sb['name']) ?>: <?= e($sb['percent']) ?>%</span><?php endforeach; ?></div></td></tr><?php endif; ?><?php endforeach; ?></tbody></table></div><?php endif; ?>
   <?php if ($at && $at['recent_absences']): ?><div class="small mt-3"><span class="text-muted">آخر أيام الغياب:</span> <?php foreach ($at['recent_absences'] as $d): ?><span class="badge text-bg-light border" dir="ltr"><?= e($d) ?></span> <?php endforeach; ?></div><?php endif; ?></div>
  <div class="row g-3">
   <div class="col-md-6"><div class="card-s h-100"><h3 class="h6">أولياء الأمور</h3><?php if (!$guardians): ?><div class="text-muted small">لا يوجد.</div><?php endif; ?><?php foreach ($guardians as $g): ?><div class="small border-bottom py-1"><strong><?= e($g['full_name']) ?></strong> <span class="badge text-bg-light border"><?= e(['father' => 'الأب', 'mother' => 'الأم', 'brother' => 'أخ', 'sister' => 'أخت', 'uncle' => 'عم/خال', 'aunt' => 'عمة/خالة', 'grandfather' => 'جد', 'grandmother' => 'جدة', 'other' => 'آخر'][$g['relation']] ?? $g['relation']) ?></span><?= $g['is_primary'] ? ' <span class="badge text-bg-primary">أساسي</span>' : '' ?><div class="text-muted" dir="ltr"><?= e($g['phone'] ?? '') ?></div></div><?php endforeach; ?></div></div>
   <div class="col-md-6"><div class="card-s h-100"><h3 class="h6">السجل الدراسي</h3><?php foreach ($enrollments as $e): ?><div class="small border-bottom py-1 d-flex justify-content-between"><span><?= e($e['year_name']) ?> — <?= e($e['grade_name'] . ' / ' . $e['section_name']) ?></span><span class="badge text-bg-<?= $e['status'] === 'active' ? 'success' : 'secondary' ?>"><?= e(['active' => 'فعّال', 'promoted' => 'مرقّى', 'repeated' => 'معيد', 'withdrawn' => 'منسحب', 'transferred' => 'منقول'][$e['status']] ?? $e['status']) ?></span></div><?php endforeach; ?><?php if (!$enrollments): ?><div class="text-muted small">لا يوجد.</div><?php endif; ?></div></div>
   <?php if ($ov['discipline'] !== null): ?><div class="col-md-6"><div class="card-s h-100"><h3 class="h6">الانضباط</h3><div class="d-flex gap-3 small"><span class="text-danger">مخالفات: <strong><?= (int)($ov['discipline']['violation'] ?? 0) ?></strong></span><span class="text-warning">إنذارات: <strong><?= (int)($ov['discipline']['warning'] ?? 0) ?></strong></span><span class="text-success">تقديرات: <strong><?= (int)($ov['discipline']['commendation'] ?? 0) ?></strong></span></div></div></div><?php endif; ?>
   <?php if ($ov['report_cards'] || $ov['credentials']): ?><div class="col-md-6"><div class="card-s h-100"><h3 class="h6">الشهادات</h3><?php foreach ($ov['report_cards'] as $rc): ?><div class="small d-flex justify-content-between border-bottom py-1"><span><?= $rc['kind'] === 'final' ? 'شهادة نهائية' : e($rc['term_name'] ?? 'شهادة') ?> — <?= e($rc['average']) ?>%</span><a target="_blank" href="<?= url('school/report-cards/' . (int)$rc['id'] . '/print') ?>">عرض</a></div><?php endforeach; ?><?php foreach ($ov['credentials'] as $c): ?><div class="small border-bottom py-1"><?= e($c['title']) ?> <?= $c['revoked_at'] ? '<span class="badge text-bg-danger">مسحوبة</span>' : '' ?></div><?php endforeach; ?></div></div><?php endif; ?>
  </div>
 </div></div>
